class CancelledBySignal extends Error {
  signal: NodeJS.Signals;
  exitCode: number;
  constructor(signal: NodeJS.Signals, exitCode: number) {
    super(`cancelled by ${signal}`);
    this.signal = signal;
    this.exitCode = exitCode;
  }
}


